files.content:
:root {
  --bg: #1a1a2e;
  --surface: #16213e;
  --primary: #e94560;
  --accent: #f5c542;
  --text: #eaeaea;
  --muted: #9aa4b8;
  --border: #0f3460;
  --focus: #f5c542;
  --radius: 0px;
  --pixel: 4px;
  font-size: 16px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--bg);
  background-image:
    linear-gradient(45deg, rgba(255,255,255,0.02) 25%, transparent 25%, transparent 75%, rgba(255,255,255,0.02) 75%),
    linear-gradient(45deg, rgba(255,255,255,0.02) 25%, transparent 25%, transparent 75%, rgba(255,255,255,0.02) 75%);
  background-size: 24px 24px;
  background-position: 0 0, 12px 12px;
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  padding: 24px 16px;
}

.app {
  width: 100%;
  max-width: 480px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.app-header { text-align: center; }

.title {
  margin: 0;
  font-size: 1.75rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 3px 3px 0 var(--border);
}

.subtitle {
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 1rem;
}

.timer-card {
  background: var(--surface);
  border: var(--pixel) solid var(--border);
  box-shadow: 8px 8px 0 rgba(0,0,0,0.35);
  padding: 24px 20px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  align-items: stretch;
}

.mode-switch {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.mode-btn {
  font: inherit;
  font-size: 1rem;
  padding: 12px 8px;
  min-height: 48px;
  background: var(--bg);
  color: var(--muted);
  border: 3px solid var(--border);
  cursor: pointer;
  transition: background 0.15s, color 0.15s, transform 0.05s;
}

.mode-btn:hover { background: var(--border); color: var(--text); }
.mode-btn:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; }
.mode-btn:active { transform: translateY(2px); }
.mode-btn.is-active {
  background: var(--accent);
  color: var(--bg);
  border-color: var(--accent);
  font-weight: 700;
}

.mode-label {
  text-align: center;
  font-size: 1rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent);
}

.countdown {
  font-family: 'Courier New', monospace;
  font-size: clamp(3.5rem, 18vw, 6rem);
  font-weight: 700;
  line-height: 1;
  text-align: center;
  color: var(--text);
  background: var(--bg);
  border: var(--pixel) solid var(--border);
  padding: 16px 8px;
  letter-spacing: 0.04em;
  font-variant-numeric: tabular-nums;
}

.countdown.is-break { color: var(--accent); }
.countdown.is-done { color: var(--primary); }

.controls {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 8px;
}

.btn {
  font: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 8px;
  min-height: 48px;
  background: var(--bg);
  color: var(--text);
  border: 3px solid var(--border);
  cursor: pointer;
  transition: background 0.15s, transform 0.05s;
}

.btn:hover { background: var(--border); }
.btn:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; }
.btn:active { transform: translateY(2px); }
.btn:disabled { opacity: 0.45; cursor: not-allowed; }

.btn-primary {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}
.btn-primary:hover { background: #c9334b; border-color: #c9334b; }

.status {
  margin: 0;
  text-align: center;
  color: var(--muted);
  font-size: 1rem;
  min-height: 1.5em;
}

.app-footer {
  text-align: center;
  color: var(--muted);
  font-size: 0.875rem;
}

.app-footer p { margin: 0; }

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 380px) {
  .controls { grid-template-columns: 1fr 1fr; }
  #reset-btn { grid-column: 1 / -1; }
  .mode-btn { font-size: 0.9rem; }
}

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; }
}

(() => {
  'use strict';

  const WORK_SECONDS = 25 * 60;
  const BREAK_SECONDS = 5 * 60;

  const state = {
    mode: 'work',
    remaining: WORK_SECONDS,
    running: false,
    endTime: 0,
    tickId: null
  };

  const countdownEl = document.getElementById('countdown');
  const modeLabelEl = document.getElementById('mode-label');
  const statusEl = document.getElementById('status');
  const startBtn = document.getElementById('start-btn');
  const pauseBtn = document.getElementById('pause-btn');
  const resetBtn = document.getElementById('reset-btn');
  const workBtn = document.getElementById('mode-work');
  const breakBtn = document.getElementById('mode-break');

  function formatTime(totalSeconds) {
    const safe = Math.max(0, Math.floor(totalSeconds));
    const m = String(Math.floor(safe / 60)).padStart(2, '0');
    const s = String(safe % 60).padStart(2, '0');
    return `${m}:${s}`;
  }

  function totalForMode(mode) {
    return mode === 'break' ? BREAK_SECONDS : WORK_SECONDS;
  }

  function render() {
    countdownEl.textContent = formatTime(state.remaining);
    countdownEl.classList.toggle('is-break', state.mode === 'break' && state.remaining > 0);
    countdownEl.classList.toggle('is-done', state.remaining === 0);
    modeLabelEl.textContent = state.mode === 'break' ? 'Break session' : 'Work session';
    startBtn.disabled = state.running || state.remaining === 0;
    pauseBtn.disabled = !state.running;
  }

  function stopTicking() {
    if (state.tickId !== null) {
      clearInterval(state.tickId);
      state.tickId = null;
    }
  }

  function tick() {
    const remainingMs = state.endTime - Date.now();
    state.remaining = Math.max(0, Math.ceil(remainingMs / 1000));

    if (state.remaining <= 0) {
      stopTicking();
      state.running = false;
      state.remaining = 0;
      statusEl.textContent = state.mode === 'work'
        ? 'Work session complete. Time for a break!'
        : 'Break complete. Back to focus!';
      render();
      return;
    }

    render();
  }

  function start() {
    if (state.running || state.remaining === 0) return;
    state.running = true;
    state.endTime = Date.now() + state.remaining * 1000;
    stopTicking();
    state.tickId = setInterval(tick, 250);
    statusEl.textContent = state.mode === 'work' ? 'Focusing... stay on task.' : 'Resting... recharge.';
    render();
  }

  function pause() {
    if (!state.running) return;
    tick();
    stopTicking();
    state.running = false;
    statusEl.textContent = 'Paused.';
    render();
  }

  function reset() {
    stopTicking();
    state.running = false;
    state.remaining = totalForMode(state.mode);
    statusEl.textContent = 'Ready to focus.';
    render();
  }

  function setMode(mode) {
    if (state.mode === mode && !state.running && state.remaining === totalForMode(mode)) return;
    stopTicking();
    state.mode = mode;
    state.running = false;
    state.remaining = totalForMode(mode);
    workBtn.classList.toggle('is-active', mode === 'work');
    breakBtn.classList.toggle('is-active', mode === 'break');
    workBtn.setAttribute('aria-pressed', String(mode === 'work'));
    breakBtn.setAttribute('aria-pressed', String(mode === 'break'));
    statusEl.textContent = mode === 'work' ? 'Ready to focus.' : 'Ready to rest.';
    render();
  }

  startBtn.addEventListener('click', start);
  pauseBtn.addEventListener('click', pause);
  resetBtn.addEventListener('click', reset);
  workBtn.addEventListener('click', () => setMode('work'));
  breakBtn.addEventListener('click', () => setMode('break'));

  document.addEventListener('keydown', (event) => {
    if (event.target.tagName === 'BUTTON' || event.target.tagName === 'INPUT') return;
    if (event.code === 'Space') {
      event.preventDefault();
      if (state.running) pause(); else start();
    } else if (event.key === 'r' || event.key === 'R') {
      reset();
    }
  });

  render();
})();
